import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Rules:
    - Each line is split on its first "=", so values may contain "=".
    - Whitespace around the name and around the value is stripped.
    - Blank lines, lines starting with "#" (after stripping), and lines
      without "=" are ignored.
    - `key` is matched exactly (case-sensitive) against the stripped name.
    - If the key appears more than once, the first occurrence wins.
    - Returns "" if the key is absent. A key present with an empty value
      also yields "".
    - Pure function: operates only on `text`, never reads files.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    text = "a=1\nb=2\nc=3"
    assert config_value(text, "a") == "1"
    assert config_value(text, "b") == "2"
    assert config_value(text, "c") == "3"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1\nb=2", "z") == ""
    assert config_value("", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =   hello world  \n", "name") == "hello world"


def test_value_contains_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""
    assert config_value("a=   \n", "a") == ""


def test_comments_and_blank_lines_ignored() -> None:
    text = "# a=commented\n\n   \na=real\n"
    assert config_value(text, "a") == "real"
    assert config_value("# a=1", "a") == ""
    assert config_value("#a=1", "#a") == ""


def test_lines_without_equals_ignored() -> None:
    assert config_value("garbage\na=1", "a") == "1"
    assert config_value("garbage", "garbage") == ""


def test_first_occurrence_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_case_sensitive_and_exact_match() -> None:
    text = "Key=upper\nkey=lower\nkeys=plural"
    assert config_value(text, "Key") == "upper"
    assert config_value(text, "key") == "lower"
    assert config_value(text, "keys") == "plural"
    assert config_value(text, "ke") == ""


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_empty_key_lookup() -> None:
    assert config_value("a=1", "") == ""


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("x=1", "x", "1"),
        ("x = 1", "x", "1"),
        ("\tx\t=\t1\t", "x", "1"),
        ("y=1", "x", ""),
    ],
)
def test_parametrized(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected
